import React, { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getSeller, getSellerProducts } from '../services/api';

const numberFrom = (...values) => {
  for (const value of values) {
    const parsed = typeof value === 'string' ? parseFloat(value) : value;
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
};

const firstValue = (obj, keys = []) => {
  if (!obj) return undefined;
  for (const key of keys) {
    if (obj[key]) return obj[key];
  }
  return undefined;
};

const formatPrice = (value) => {
  if (typeof value !== 'number') return '';
  try {
    return new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(value);
  } catch (err) {
    console.error(err);
    return `$ ${value}`;
  }
};

export default function SellerPage() {
  const { id } = useParams();
  const [seller, setSeller] = useState(null);
  const [products, setProducts] = useState([]);

  useEffect(() => {
    let isMounted = true;
    (async () => {
      try {
        const sData = await getSeller(id);
        if (!isMounted) return;
        setSeller(sData);
        const prodData = await getSellerProducts(id);
        if (!isMounted) return;
        setProducts(prodData || []);
      } catch (error) {
        console.error('SellerPage load failed', error);
      }
    })();
    return () => {
      isMounted = false;
    };
  }, [id]);

  const goBack = () =>
    window.history.length > 1 ? window.history.back() : (window.location.href = '/');

  const mapData = useMemo(() => {
    if (!seller) return { hasCoords: false };
    const lat = numberFrom(
      seller.latitude,
      seller.lat,
      seller.geoLat,
      seller.geoLatitude,
      seller.locationLat,
      seller.locationLatitude
    );
    const lng = numberFrom(
      seller.longitude,
      seller.lng,
      seller.geoLng,
      seller.geoLongitude,
      seller.locationLng,
      seller.locationLongitude
    );
    if (lat === null || lng === null) return { hasCoords: false };
    return {
      hasCoords: true,
      lat,
      lng,
      embedUrl: `https://maps.google.com/maps?q=${lat},${lng}&z=15&output=embed`
    };
  }, [seller]);

  const socialLinks = useMemo(() => {
    if (!seller) return [];
    const fb = firstValue(seller, ['facebookUrl', 'facebook', 'facebookLink', 'socialFacebook']);
    const ig = firstValue(seller, ['instagramUrl', 'instagram', 'instagramLink', 'socialInstagram']);
    const waDirect = firstValue(seller, ['whatsappUrl', 'whatsapp', 'whatsappLink', 'socialWhatsapp']);
    const phone = seller.contactPhone ? seller.contactPhone.replace(/[^0-9+]/g, '') : '';
    const waFallback = phone.length >= 6 ? `https://wa.me/${phone.replace(/[^0-9]/g, '')}` : null;
    return [
      { id: 'facebook', label: 'Facebook', href: fb },
      { id: 'instagram', label: 'Instagram', href: ig },
      { id: 'whatsapp', label: 'Whatsapp', href: waDirect || waFallback }
    ].filter((item) => !!item.href);
  }, [seller]);

  if (!seller) return <div className="loading">Cargando…</div>;

  const bannerImage =
    seller.bannerImageUrl ||
    seller.coverImageUrl ||
    seller.coverUrl ||
    seller.imageBanner ||
    seller.imageUrl ||
    '/placeholder.png';

  return (
    <div className="cp-seller-page">
      <section
        className="seller-hero"
        style={{ backgroundImage: `linear-gradient(rgba(247, 211, 74, 0.5), rgba(247, 211, 74, 0.5)), url(${bannerImage})` }}
        aria-label={`Banner de ${seller.name}`}
      >
        <div className="seller-hero__logo-wrap">
          <img src="/logo.png" alt="Conecta Pinamar" className="seller-hero__logo" />
        </div>
      </section>

      <section className="seller-summary">
        <img className="seller-summary__avatar" src={seller.imageUrl || '/placeholder.png'} alt={seller.name} />
        <div className="seller-summary__body">
          <h1>{seller.name}</h1>
          {seller.location && <p className="seller-summary__location">{seller.location}</p>}
          {seller.description && <p className="seller-summary__description">{seller.description}</p>}
          <div className="seller-summary__contact">
            {seller.contactPhone && <div>Tel: {seller.contactPhone}</div>}
            {seller.contactEmail && <div>Email: {seller.contactEmail}</div>}
          </div>
        </div>
      </section>

      <section className="seller-products">
        <h2>Productos del vendedor</h2>
        <div className="seller-products__grid">
          {products.map((product) => (
            <a key={product.id} className="seller-product" href={`/producto/${product.id}`}>
              <div className="seller-product__thumb">
                <img src={product.imageUrl || '/placeholder.png'} alt={product.name} loading="lazy" />
              </div>
              <div className="seller-product__info">
                <div className="seller-product__name">{product.name}</div>
                {product.price != null && (
                  <div className="seller-product__price">{formatPrice(product.price)}</div>
                )}
              </div>
            </a>
          ))}
          {products.length === 0 && (
            <div className="seller-products__empty">Este vendedor todavía no cargó productos.</div>
          )}
        </div>
      </section>

      <section className="seller-location">
        <h2>Ubicación</h2>
        {mapData.hasCoords ? (
          <div className="seller-location__map">
            <iframe
              title={`Ubicación de ${seller.name}`}
              src={mapData.embedUrl}
              loading="lazy"
              allowFullScreen
            />
          </div>
        ) : (
          <p className="seller-location__placeholder">El vendedor todavía no cargó su ubicación.</p>
        )}
      </section>

      <section className="seller-more">
        <h2>Saber más</h2>
        {socialLinks.length ? (
          <div className="seller-more__actions">
            {socialLinks.map((link) => (
              <a key={link.id} className={`seller-social seller-social--${link.id}`} href={link.href} target="_blank" rel="noopener noreferrer">
                {link.label}
              </a>
            ))}
          </div>
        ) : (
          <p className="seller-more__placeholder">El vendedor no agregó enlaces a redes sociales.</p>
        )}
      </section>

      <button className="seller-back" onClick={goBack}>
        ← volver a la pagina anterior
      </button>
    </div>
  );
}
